    private sealed class XhttpVmValidation(ArchiveStore store, ClientRouteDiagnostics diagnostics, JsonObject host) : IInboundValidation
    {
        public bool BadSni, Cancel; public int XhttpValidated;
        public async Task<JsonObject> ValidateAsync(JsonObject plan, JsonObject model, JsonObject credentials, string[] ids, string directory, IProgress<string> progress, CancellationToken ct)
        {
            if (Cancel) throw new OperationCanceledException("Synthetic cancellation after apply."); var items = new JsonArray();
            foreach (var node in InboundRendering.Nodes(store, plan.Text("Provider") + "/" + plan.Text("Instance") + "/May-VPS-Deploy", plan, model, credentials).Where(n => ids.Contains(n.Text("InboundOrigin.InboundId"))))
            {
                var copy = node.DeepClone().AsObject(); var guestPort=node.Number("clash.port");
                await using var tunnel=VlessXhttp.IsNode(copy)&&VlessXhttp.NodeVersion(copy)=="3"?await HysteriaVmTunnel.Start(host,guestPort,ct):null;
                var port = tunnel?.Port??host["Applications"]!.AsObject().Number(guestPort.ToString()); copy["clash"]!["server"] = "127.0.0.1"; copy["clash"]!["port"] = port; if (copy["sing_box"] is JsonObject native) { native["server"] = "127.0.0.1"; native["server_port"] = port; }
                if (BadSni && VlessXhttp.IsNode(copy)) { copy["clash"]!["servername"] = "wrong.example.test";copy["sing_box"]!["tls"]!["server_name"]="wrong.example.test"; }
                var scheme = new JsonObject { ["Nodes"] = new JsonArray(copy), ["Layout"] = new JsonObject { ["region_groups"] = new JsonArray(copy.Text("region_group")) } }; var result = await diagnostics.RunAsync(ClientTopology.DiagnosticRoute(scheme, copy.Text("name")), directory, progress, ct);
                if (VlessXhttp.IsNode(copy) && VlessXhttp.Evidence(copy, result)) XhttpValidated++;
                if (result.Text("Status") != "Reachable") Console.WriteLine("XHTTP VM diagnostic: " + result["Stages"]!.ToJsonString());
                items.Add(new JsonObject { ["InboundId"] = node.Text("InboundOrigin.InboundId"), ["UserId"] = node.Text("InboundOrigin.UserId"), ["Family"] = node.Text("InboundOrigin.Family"), ["ConnectionFingerprint"] = ClientNodeImport.ConnectionFingerprint(node), ["Status"] = result.Text("Status") == "Reachable" ? "Passed" : "Incomplete", ["From"] = "Controller", ["Scope"] = "ProxyHttps", ["Result"] = result });
            }
            return new JsonObject { ["Status"] = items.All(i => i!.Text("Status") == "Passed") ? "Passed" : "Incomplete", ["Items"] = items };
        }
